public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize graph and cost arrays
    List<List<Integer>> graph = new ArrayList<>(n);
    int[] cost = new int[n];
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
        cost[i] = 0;
    }

    // Build graph and calculate costs
    for (int[] edge : edges) {
        int from = edge[0];
        int to = edge[1];
        int weight = 1;
        if (hasApple[from] || hasApple[to]) {
            weight = 2;
        }
        graph.get(from).add(to);
        graph.get(to).add(from);
        cost[from] += weight;
        cost[to] += weight;
    }

    // Initialize and fill distance and parent arrays
    int[] distance = new int[n];
    int[] parent = new int[n];
    Arrays.fill(distance, -1);
    distance[0] = 0;

    // Fill distance and parent arrays
    for (int current = 0; current != -1; ) {
        if (current == n) {
            break;
        }
        for (int next : graph.get(current)) {
            if (distance[next] == -1 || distance[next] > distance[current] + cost[next]) {
                distance[next] = distance[current] + cost[next];
                parent[next] = current;
            }
        }
        current = -1;
        for (int i = 0; i < n; i++) {
            if (distance[i] > distance[current]) {
                current = i;
            }
        }
    }

    // Compute and return minimum time
    int time = 0;
    for (int node = 0; node != n; node++) {
        if (hasApple[node]) {
            time += distance[node];
        }
    }
    return time;
}
