import java.util.Arrays;

public class SquarePermutations {

    static int squarePermutations(int[] A) {
        if (A == null || A.length <= 0) {
            return 0;
        }

        // Sort the array and compute the sum of each pair of adjacent elements
        Arrays.sort(A);
        int sum1 = 0;
        for (int i = 0; i < A.length - 1; i++) {
            sum1 += A[i];
        }

        // Initialize the result variable
        int result = 1;

        // Check if the first and last elements are the same or not
        boolean firstAndLastAreSame = A[0] == A[A.length - 1];

        // If the first and last elements are the same, then we have a square array
        if (firstAndLastAreSame) {
            result++;
        }

        // If the sum of the first and last elements is a perfect square, then we have a square array
        int sumOfFirstAndLast = A[0] + A[A.length - 1];
        if (Math.sqrt(sumOfFirstAndLast) % 1 == 0) {
            result++;
        }

        // Check if the sum of each pair of adjacent elements is a perfect square
        for (int i = 0; i < A.length - 1; i++) {
            if (Math.sqrt(sum1) % 1 == 0) {
                result++;
                break;
            }
            sum1 -= A[i];
            sum1 += A[i + 1];
        }

        return result;
    }

    public static void main(String[] args) {
        int[] A = new int[]{1, 17, 8};
        System.out.println("squarePermutations(new int[]{1, 17, 8}): " + squarePermutations(A));

        A = new int[]{2, 2, 2};
        System.out.println("squarePermutations(new int[]{2, 2, 2}): " + squarePermutations(A));
    }
}

