public static int largestRectangleArea(int[] heights) {
	int maxArea = 0;
	Stack<Integer> st = new Stack<>();
	for (int i = 0; i < heights.length; i++) {
		while (!st.isEmpty() && heights[st.peek()] > heights[i]) {
			int curH = heights[st.pop()];
			int curW = i - 1 - st.peek();
			if (curH > maxArea) {
				maxArea = curH * curW;
			}
		}
		st.push(i);
	}
	while (!st.isEmpty()) {
		int curH = heights[st.pop()];
		int curW = i - 1 - st.peek();
		if (curH > maxArea) {
			maxArea = curH * curW;
		}
	}
	return maxArea;
}

