public class FindSmallestInteger {
    public static int findSmallestInteger(int n) {
        // Sort the digits of n in ascending order
        List<Integer> digits = new ArrayList<>(Arrays.asList(String.valueOf(n).split("")));
        Collections.sort(digits);

        // Build the smallest rearranged integer
        int smallest = 0;
        for (int i = 0; i < digits.size(); i++) {
            smallest += digits.get(i) * (int) Math.pow(10, i);
        }

        // Check if smallest is greater than n
        if (smallest <= n) {
            return -1;
        }

        return smallest;
    }
