public static boolean isBoomerang(int[][] points) {
    // Calculate the distance between each adjacent pair of points
    for (int i = 0; i < points.length - 2; i++) {
        for (int j = i + 1; j < points.length - 1; j++) {
            int dx = points[j][0] - points[i][0];
            int dy = points[j][1] - points[i][1];
            if (dx == 0 && dy == 0) {
                // The points are on the same line, return false
                return false;
            }
        }
    }

    // Calculate the distance between the first point and the last point
    int dx1 = points[points.length - 1][0] - points[0][0];
    int dy1 = points[points.length - 1][1] - points[0][1];

    // Calculate the distance between the second-last point and the last point
    int dx2 = points[points.length - 1][0] - points[points.length - 2][0];
    int dy2 = points[points.length - 1][1] - points[points.length - 2][1];

    // If the cross product of the vectors (dx1, dy1) and (dx2, dy2) is negative,
    // the points form a boomerang.
    if (dx1 * dy2 - dy1 * dx2 < 0) {
        return true;
    }

    // Otherwise, the points do not form a boomerang.
    return false;
}

